// Extract user IDs for subsequent earnings lookups
const items = Array.isArray($input.all()) ? $input.all() : [$input.first()];
const users = [];

for (const item of items) {
  const data = item.json;
  const usersArray = Array.isArray(data) ? data : (data.data ? data.data : [data]);

  for (const u of usersArray) {
    users.push({
      json: {
        userId: u.id || u._id,
        name: u.name,
        phone: u.phone
      }
    });
  }
}

if (users.length === 0) {
  return [{ json: { noUsers: true, message: 'No users found' } }];
}

return users;

// Analyze earnings and forecast data for alert conditions
const alerts = [];
const items = $input.all();

for (const item of items) {
  const data = item.json;
  const userId = data.userId;

  // Alert: Income drop (current week vs previous week > 30% drop)
  if (data.currentWeekEarnings !== undefined && data.previousWeekEarnings !== undefined) {
    const prevWeek = data.previousWeekEarnings;
    const currWeek = data.currentWeekEarnings;

    if (prevWeek > 0) {
      const dropPercent = ((prevWeek - currWeek) / prevWeek) * 100;
      if (dropPercent > 30) {
        alerts.push({
          json: {
            userId,
            type: 'income_drop',
            severity: dropPercent > 50 ? 'critical' : 'warning',
            title: 'Income Drop Detected',
            message: `Your income dropped ${Math.round(dropPercent)}% compared to last week`,
            data: { currentWeek: currWeek, previousWeek: prevWeek, dropPercent: Math.round(dropPercent) }
          }
        });
      }
    }
  }

  // Alert: Low buffer (predicted income < expenses)
  if (data.forecastedMonthlyIncome !== undefined && data.estimatedExpenses !== undefined) {
    const buffer = data.forecastedMonthlyIncome - data.estimatedExpenses;
    if (buffer < 2000) {
      alerts.push({
        json: {
          userId,
          type: 'buffer_low',
          severity: buffer < 0 ? 'critical' : 'warning',
          title: 'Low Financial Buffer',
          message: buffer < 0 
            ? `Projected shortfall of ₹${Math.abs(Math.round(buffer))} this month` 
            : `Financial buffer is only ₹${Math.round(buffer)} this month`,
          data: { forecastedIncome: data.forecastedMonthlyIncome, expenses: data.estimatedExpenses, buffer: Math.round(buffer) }
        }
      });
    }
  }

  // Alert: Expense spike
  if (data.currentMonthExpenses !== undefined && data.averageMonthlyExpenses !== undefined) {
    const avgExpenses = data.averageMonthlyExpenses;
    const currExpenses = data.currentMonthExpenses;

    if (avgExpenses > 0) {
      const spikePercent = ((currExpenses - avgExpenses) / avgExpenses) * 100;
      if (spikePercent > 25) {
        alerts.push({
          json: {
            userId,
            type: 'expense_spike',
            severity: spikePercent > 50 ? 'critical' : 'warning',
            title: 'Expense Spike Detected',
            message: `Your expenses are ${Math.round(spikePercent)}% higher than your average`,
            data: { currentExpenses: currExpenses, averageExpenses: avgExpenses, spikePercent: Math.round(spikePercent) }
          }
        });
      }
    }
  }
}

if (alerts.length === 0) {
  return [{ json: { noAlerts: true, message: 'No financial alerts generated', checkedAt: new Date().toISOString() } }];
}

return alerts;
